#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Convert markdown to HTML using a markdown library
    // This is a simplified example and may not cover all markdown features
    // In a real-world scenario, you would use a proper markdown parser library
    // such as Pandoc or Markdown.

    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        html += line + "\n";
    }
    return html;
}

int main() {
    std::string markdown = "# Hello, World!\nThis is a markdown text.\nIt will be converted to HTML.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

